import React from "react";
import "./../css/form.css";
import {
  FaUser,
  FaPhone,
  FaMapMarkerAlt,
  FaImage,
  FaTag,
  FaQuestionCircle,
  FaClock,
  FaLink,
} from "react-icons/fa";

class CustomerRequestForm extends React.Component {
  constructor(props) {
    super(props);

    this.API_URL = "https://iranaserviceapp.ir/test/api";

    this.state = {
      fullName: "",
      mobile: "",
      landline: "",

      province: "",
      city: "",

      deviceType: "",
      deviceBrand: "",

      deviceIssue: "",
      visitTime: "",
      description: "",
      address: "",

      states: [],
      cities: [],
      types: [],
      brands: [],

      loadingStates: false,
      loadingCities: false,
      loadingTypesBrands: false,
      submitting: false,

      error: "",
      success: "",
    };

    this.handleChange = this.handleChange.bind(this);
    this.handleSubmit = this.handleSubmit.bind(this);
    this.loadStates = this.loadStates.bind(this);
    this.loadCities = this.loadCities.bind(this);
    this.loadTypesBrands = this.loadTypesBrands.bind(this);
  }

  componentDidMount() {
    this.loadStates();
    this.loadTypesBrands();
  }

  handleChange(field) {
    return (e) => {
      const value = e.target.value;

      this.setState({
        [field]: value,
        error: "",
        success: "",
      });

      if (field === "province") {
        this.setState({
          city: "",
          cities: [],
        });

        if (value) {
          this.loadCities(value);
        }
      }
    };
  }

  async loadStates() {
    this.setState({
      loadingStates: true,
      error: "",
    });

    try {
      const response = await fetch(`${this.API_URL}/cities`, {
        method: "GET",
        headers: {
          Accept: "application/json",
        },
      });

      if (!response.ok) {
        throw new Error(`HTTP Error: ${response.status}`);
      }

      const data = await response.json();

      if (data.status === "1") {
        this.setState({
          states: data.states || [],
          loadingStates: false,
        });
      } else {
        this.setState({
          loadingStates: false,
          error: data.message || "دریافت استان‌ها انجام نشد",
        });
      }
    } catch (error) {
      console.error("loadStates error:", error);

      this.setState({
        loadingStates: false,
        error: "خطا در ارتباط با سرور برای دریافت استان‌ها",
      });
    }
  }

  async loadCities(stateId) {
    this.setState({
      loadingCities: true,
      cities: [],
      city: "",
      error: "",
    });

    try {
      const response = await fetch(
        `${this.API_URL}/cities?id=${encodeURIComponent(stateId)}`,
        {
          method: "GET",
          headers: {
            Accept: "application/json",
          },
        }
      );

      if (!response.ok) {
        throw new Error(`HTTP Error: ${response.status}`);
      }

      const data = await response.json();

      if (data.status === "1") {
        this.setState({
          cities: data.cities || [],
          loadingCities: false,
        });
      } else {
        this.setState({
          cities: [],
          loadingCities: false,
          error: data.message || "دریافت شهرها انجام نشد",
        });
      }
    } catch (error) {
      console.error("loadCities error:", error);

      this.setState({
        cities: [],
        loadingCities: false,
        error: "خطا در دریافت شهرها از سرور",
      });
    }
  }

  async loadTypesBrands() {
    this.setState({
      loadingTypesBrands: true,
      error: "",
    });

    try {
      const response = await fetch(`${this.API_URL}/list-type`, {
        method: "GET",
        headers: {
          Accept: "application/json",
        },
      });

      if (!response.ok) {
        throw new Error(`HTTP Error: ${response.status}`);
      }

      const data = await response.json();

      if (data.status === "1") {
        this.setState({
          types: data.types || [],
          brands: data.brands || [],
          loadingTypesBrands: false,
        });
      } else {
        this.setState({
          loadingTypesBrands: false,
          error: data.message || "دریافت نوع و برند انجام نشد",
        });
      }
    } catch (error) {
      console.error("loadTypesBrands error:", error);

      this.setState({
        loadingTypesBrands: false,
        error: "خطا در دریافت نوع و برند دستگاه",
      });
    }
  }

  async handleSubmit(e) {
    e.preventDefault();

    const {
      fullName,
      mobile,
      landline,
      province,
      city,
      deviceType,
      deviceBrand,
      deviceIssue,
      visitTime,
      description,
      address,
    } = this.state;

    this.setState({
      error: "",
      success: "",
    });

    if (!fullName.trim()) {
      this.setState({
        error: "نام کامل را وارد کنید",
      });
      return;
    }

    if (!mobile.trim()) {
      this.setState({
        error: "شماره موبایل را وارد کنید",
      });
      return;
    }

    if (!province) {
      this.setState({
        error: "استان را انتخاب کنید",
      });
      return;
    }

    if (!city) {
      this.setState({
        error: "شهر را انتخاب کنید",
      });
      return;
    }

    if (!deviceType) {
      this.setState({
        error: "نوع دستگاه را انتخاب کنید",
      });
      return;
    }

    if (!deviceBrand) {
      this.setState({
        error: "برند دستگاه را انتخاب کنید",
      });
      return;
    }

    if (!deviceIssue.trim()) {
      this.setState({
        error: "ایراد دستگاه را وارد کنید",
      });
      return;
    }

    const token = localStorage.getItem("token");

    this.setState({
      submitting: true,
    });

    try {
      const response = await fetch(`${this.API_URL}/create`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Accept: "application/json",

          ...(token
            ? {
                Authorization: `Bearer ${token}`,
              }
            : {}),
        },
        body: JSON.stringify({
          name: fullName.trim(),
          mobile: mobile.trim(),
          mobile2: landline.trim(),

          // ID استان
          state: province,

          // ID شهر
          city: city,

          // ID برند
          device_brand: deviceBrand,

          // ID نوع دستگاه
          device_type: deviceType,

          // آدرس
          address: address.trim(),

          // مشکل دستگاه
          problem: deviceIssue.trim(),

          // توضیحات
          description: description.trim(),

          // زمان مراجعه
          time: visitTime.trim(),
        }),
      });

      if (!response.ok) {
        throw new Error(`HTTP Error: ${response.status}`);
      }

      const data = await response.json();

      if (data.status === "1") {
        this.setState({
          submitting: false,
          success: data.message || "درخواست با موفقیت ثبت شد",

          fullName: "",
          mobile: "",
          landline: "",
          province: "",
          city: "",
          deviceType: "",
          deviceBrand: "",
          deviceIssue: "",
          visitTime: "",
          description: "",
          address: "",

          cities: [],
        });
      } else {
        this.setState({
          submitting: false,
          error: data.message || "ثبت درخواست انجام نشد",
        });
      }
    } catch (error) {
      console.error("create request error:", error);

      this.setState({
        submitting: false,
        error: "خطا در ارتباط با سرور برای ثبت درخواست",
      });
    }
  }

  render() {
    const {
      fullName,
      mobile,
      landline,
      province,
      city,
      deviceType,
      deviceBrand,
      deviceIssue,
      visitTime,
      description,
      address,

      states,
      cities,
      types,
      brands,

      loadingStates,
      loadingCities,
      loadingTypesBrands,
      submitting,

      error,
      success,
    } = this.state;

    return (
      <div className="container pt-3">
        <div
          className="mx-auto"
          style={{
            maxWidth: "480px",
          }}
        >
          <h6 className="text-center fw-bold text-dark mb-4">
            اطلاعات مشتری را با دقت ثبت کنید
          </h6>

          {error && (
            <div
              className="alert alert-danger text-center"
              style={{
                fontSize: "13px",
                borderRadius: "12px",
              }}
            >
              {error}
            </div>
          )}

          {success && (
            <div
              className="alert alert-success text-center"
              style={{
                fontSize: "13px",
                borderRadius: "12px",
              }}
            >
              {success}
            </div>
          )}

          <form onSubmit={this.handleSubmit}>
            {/* نام کامل */}
            <div className="custom-input mb-3">
              <div className="custom-icon">
                <FaUser />
              </div>

              <input
                type="text"
                placeholder="نام کامل"
                value={fullName}
                onChange={this.handleChange("fullName")}
              />
            </div>

            {/* شماره موبایل */}
            <div className="custom-input mb-3">
              <div className="custom-icon">
                <FaPhone />
              </div>

              <input
                type="tel"
                inputMode="numeric"
                placeholder="شماره موبایل"
                value={mobile}
                onChange={this.handleChange("mobile")}
              />
            </div>

            {/* تلفن ثابت */}
            <div className="custom-input mb-3">
              <div className="custom-icon">
                <FaPhone />
              </div>

              <input
                type="tel"
                inputMode="numeric"
                placeholder="تلفن ثابت"
                value={landline}
                onChange={this.handleChange("landline")}
              />
            </div>

            {/* استان */}
            <div className="custom-input mb-3">
              <div className="custom-icon">
                <FaMapMarkerAlt />
              </div>

              <select
                value={province}
                onChange={this.handleChange("province")}
                disabled={loadingStates}
              >
                <option value="" disabled>
                  {loadingStates
                    ? "در حال دریافت استان‌ها..."
                    : "استان"}
                </option>

                {states.map((state) => (
                  <option key={state.id} value={state.id}>
                    {state.name}
                  </option>
                ))}
              </select>
            </div>

            {/* شهر */}
            <div className="custom-input mb-3">
              <div className="custom-icon">
                <FaMapMarkerAlt />
              </div>

              <select
                value={city}
                onChange={this.handleChange("city")}
                disabled={!province || loadingCities}
              >
                <option value="" disabled>
                  {!province
                    ? "ابتدا استان را انتخاب کنید"
                    : loadingCities
                    ? "در حال دریافت شهرها..."
                    : "شهر"}
                </option>

                {cities.map((item) => (
                  <option key={item.id} value={item.id}>
                    {item.name}
                  </option>
                ))}
              </select>
            </div>

            {/* نوع دستگاه */}
            <div className="custom-input mb-3">
              <div className="custom-icon">
                <FaImage />
              </div>

              <select
                value={deviceType}
                onChange={this.handleChange("deviceType")}
                disabled={loadingTypesBrands}
              >
                <option value="" disabled>
                  {loadingTypesBrands
                    ? "در حال دریافت..."
                    : "نوع دستگاه"}
                </option>

                {types.map((type) => (
                  <option key={type.id} value={type.id}>
                    {type.name}
                  </option>
                ))}
              </select>
            </div>

            {/* برند دستگاه */}
            <div className="custom-input mb-3">
              <div className="custom-icon">
                <FaTag />
              </div>

              <select
                value={deviceBrand}
                onChange={this.handleChange("deviceBrand")}
                disabled={loadingTypesBrands}
              >
                <option value="" disabled>
                  {loadingTypesBrands
                    ? "در حال دریافت..."
                    : "برند دستگاه"}
                </option>

                {brands.map((brand) => (
                  <option key={brand.id} value={brand.id}>
                    {brand.name}
                  </option>
                ))}
              </select>
            </div>

            {/* ایراد دستگاه */}
            <div className="custom-input mb-3">
              <div className="custom-icon">
                <FaQuestionCircle />
              </div>

              <input
                type="text"
                placeholder="ایراد دستگاه"
                value={deviceIssue}
                onChange={this.handleChange("deviceIssue")}
              />
            </div>

            {/* زمان مراجعه */}
            <div className="custom-input mb-3">
              <div className="custom-icon">
                <FaClock />
              </div>

              <input
                type="text"
                placeholder="زمان مراجعه"
                value={visitTime}
                onChange={this.handleChange("visitTime")}
              />
            </div>

            {/* آدرس */}
            <div className="custom-input mb-3">
              <div className="custom-icon">
                <FaMapMarkerAlt />
              </div>

              <input
                type="text"
                placeholder="آدرس"
                value={address}
                onChange={this.handleChange("address")}
              />
            </div>

            {/* توضیحات */}
            <div className="custom-input mb-3">
              <div className="custom-icon">
                <FaLink />
              </div>

              <input
                type="text"
                placeholder="توضیحات"
                value={description}
                onChange={this.handleChange("description")}
              />
            </div>

            {/* دکمه */}
            <button
              type="submit"
              className="btn btn-sub w-100 fw-bold py-2 rounded-4"
              disabled={submitting}
            >
              <small>
                {submitting
                  ? "در حال ثبت..."
                  : "ثبت درخواست"}
              </small>
            </button>
          </form>
        </div>
      </div>
    );
  }
}

export default CustomerRequestForm;
